import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Container, Row, Col, Card, Form, Button, Alert, Spinner } from 'react-bootstrap';
import { useAuth } from '../../contexts/AuthContext';
import { toast } from 'react-toastify';

const Login = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: ''
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
    // Clear error when user starts typing
    if (error) setError('');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      console.log('🔐 Attempting login with:', { email: formData.email });
      const result = await login(formData);
      console.log('🔍 Login result:', result);
      
      if (result.success) {
        console.log('✅ Login successful, navigating to dashboard');
        toast.success('Login berhasil! Selamat datang.');
        navigate('/dashboard');
      } else {
        console.log('❌ Login failed:', result.message);
        setError(result.message || 'Login gagal. Silakan periksa email dan password Anda.');
        toast.error(result.message || 'Login gagal');
      }
    } catch (error) {
      console.error('💥 Login error:', error);
      const errorMessage = 'Terjadi kesalahan saat login. Silakan coba lagi.';
      setError(errorMessage);
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-container d-flex align-items-center justify-content-center">
      <Container>
        <Row className="justify-content-center">
          <Col xs={12} sm={8} md={6} lg={5} xl={4}>
            <Card className="fade-in-up">
              <Card.Header className="text-center border-0">
                <div className="mb-3">
                  <i className="fas fa-building text-white" style={{ fontSize: '3rem' }}></i>
                </div>
                <h2 className="text-white mb-0 fw-bold">BRIRoom</h2>
                <p className="text-white-50 mb-0">Sistem Booking Ruangan</p>
              </Card.Header>
              
              <Card.Body>
                <div className="text-center mb-4">
                  <h4 className="fw-bold text-primary mb-2">Selamat Datang</h4>
                  <p className="text-muted">Masuk ke akun Anda untuk melanjutkan</p>
                </div>

                {error && (
                  <Alert variant="danger" className="d-flex align-items-center">
                    <i className="fas fa-exclamation-triangle me-2"></i>
                    {error}
                  </Alert>
                )}

                <Form onSubmit={handleSubmit}>
                  <Form.Group className="mb-4">
                    <Form.Label className="fw-semibold">
                      <i className="fas fa-envelope me-2 text-primary"></i>
                      Email
                    </Form.Label>
                    <Form.Control
                      type="email"
                      name="email"
                      placeholder="Masukkan email Anda"
                      value={formData.email}
                      onChange={handleChange}
                      required
                      disabled={loading}
                      className="form-control-lg"
                    />
                  </Form.Group>

                  <Form.Group className="mb-4">
                    <Form.Label className="fw-semibold">
                      <i className="fas fa-lock me-2 text-primary"></i>
                      Password
                    </Form.Label>
                    <Form.Control
                      type="password"
                      name="password"
                      placeholder="Masukkan password Anda"
                      value={formData.password}
                      onChange={handleChange}
                      required
                      disabled={loading}
                      className="form-control-lg"
                    />
                  </Form.Group>

                  <div className="d-grid gap-2">
                    <Button 
                      type="submit" 
                      variant="primary" 
                      size="lg"
                      disabled={loading}
                      className="fw-bold"
                    >
                      {loading ? (
                        <>
                          <Spinner
                            as="span"
                            animation="border"
                            size="sm"
                            role="status"
                            aria-hidden="true"
                            className="me-2"
                          />
                          Memproses...
                        </>
                      ) : (
                        <>
                          <i className="fas fa-sign-in-alt me-2"></i>
                          Masuk
                        </>
                      )}
                    </Button>
                  </div>
                </Form>

                <div className="text-center mt-4">
                  <div className="d-flex align-items-center justify-content-center mb-3">
                    <hr className="flex-grow-1" />
                    <span className="mx-3 text-muted small">Atau</span>
                    <hr className="flex-grow-1" />
                  </div>
                  <p className="text-muted small mb-0">
                    <i className="fas fa-info-circle me-1"></i>
                    Hubungi administrator untuk mendapatkan akses
                  </p>
                </div>
              </Card.Body>
            </Card>

            {/* Demo Accounts Info */}
            <Card className="mt-3 fade-in-up" style={{ animationDelay: '0.2s' }}>
              <Card.Body className="text-center py-3">
                <h6 className="text-primary fw-bold mb-2">
                  <i className="fas fa-users me-2"></i>
                  Demo Accounts
                </h6>
                <div className="row text-start">
                  <div className="col-md-4 mb-2">
                    <small className="text-muted d-block fw-bold">User:</small>
                    <small className="text-dark">user@bri.co.id</small>
                  </div>
                  <div className="col-md-4 mb-2">
                    <small className="text-muted d-block fw-bold">Admin:</small>
                    <small className="text-dark">admin@bri.co.id</small>
                  </div>
                  <div className="col-md-4 mb-2">
                    <small className="text-muted d-block fw-bold">Logistik:</small>
                    <small className="text-dark">logistik@bri.co.id</small>
                  </div>
                </div>
                <small className="text-muted">Password: password123</small>
              </Card.Body>
            </Card>
          </Col>
        </Row>
      </Container>
    </div>
  );
};

export default Login;
